 47	export async function extractArchive(data: Uint8Array, url: string, root: string): Promise<void> {
 48	  if (/\.zip(?:\?|$)/i.test(url)) {
 49	    let declared = 0;
 50	    const entries = unzipSync(data, { filter: file => { declared += file.originalSize; if (declared > 1024 * 1024 * 1024) throw new Error('解压文件超过 1 GiB'); return true; } });
 51	    let total = 0;
 52	    for (const [path, bytes] of Object.entries(entries)) {
 53	      const full = safePath(root, path);
 54	      total += bytes.length;
 55	      if (total > 1024 * 1024 * 1024) throw new Error('解压文件超过 1 GiB');
 56	      if (path.endsWith('/')) { await mkdir(full, { recursive: true }); continue; }
 57	      await mkdir(dirname(full), { recursive: true });
 58	      await writeFile(full, bytes, { flag: 'wx' });
 59	    }
 60	    return;
 61	  }
 62	  const archive = join(root, '.archive');
 63	  await writeFile(archive, data);
 64	  let total = 0;
 65	  let invalid: Error | undefined;
 66	  await listTar({ file: archive, strict: true, onReadEntry: entry => {
 67	    if (entry.path === './' || entry.path === '.') return;
 68	    try {
 69	      safePath(root, entry.path);
 70	      if (!['File', 'Directory', 'ExtendedHeader', 'GlobalExtendedHeader'].includes(entry.type)) throw new Error('安装包不允许符号链接或硬链接');
 71	      total += entry.size;
 72	      if (total > 1024 * 1024 * 1024) throw new Error('解压文件超过 1 GiB');
 73	    } catch (error) { invalid = error instanceof Error ? error : new Error(String(error)); }
 74	  } });
 75	  if (invalid) throw invalid;
 76	  await extractTar({ file: archive, cwd: root, strict: true, preservePaths: false });
 77	  await rm(archive);
